contentFull:
说明：命令按 V8R6、V9 常见语法整理。不同小版本、兼容模式（Oracle、MySQL）及插件版本下，sys_ 与 pg_ 前缀、集群工具参数可能存在差异；执行前请用 ksql \h、sys_ctl --help、对应工具 --help 核对，破坏性命令务必先在测试环境验证。


一、连接与实例基础管理（1–30）

ksql -U system -d test -h 127.0.0.1 -p 54321：本地或远程连接
ksql -U system -d test -W：连接时提示输入密码
ksql -U system -d test -c "SELECT version();"：执行单条 SQL
ksql -U system -d test -f /home/kes/check.sql：执行脚本文件
ksql -U system -d test -o /home/kes/out.txt -c "SELECT now();"：结果输出到文件
ksql -l：列出实例内所有数据库
ksql -U system -d test -c "\l"：列出数据库及属主、编码
\c dbname：切换数据库
\conninfo：查看当前���接信息
\dn：列出 schema
\dt：列出当前 schema 表
\d+ tablename：查看表结构、存储、分布信息
\di：列出索引
\dv：列出视图
\df：列出函数
\du：列出用户与角色
\dx：列出已安装扩展
\dp：查看对象权限
\timing on：开启 SQL 执行耗时显示
\x：切换扩展显示模式
\encoding：查看客户端字符编码
\q：退出 ksql
sys_ctl status -D $KINGBASE_DATA：查看实例运行状态
sys_ctl start -D $KINGBASE_DATA -l $KINGBASE_DATA/log/start.log：启动实例
sys_ctl stop -D $KINGBASE_DATA -m fast：快速停止实例
sys_ctl restart -D $KINGBASE_DATA -m fast：重启实例
sys_ctl reload -D $KINGBASE_DATA：重载配置文件
sys_ctl promote -D $KINGBASE_DATA：备库提升为主库
sys_isready -h 127.0.0.1 -p 54321：探测实例是否可连接
sys_controldata -D $KINGBASE_DATA：查看控制文件与集群状态


二、日常巡检（31–120）
2.1 实例与版本

SELECT version();
SELECT current_database(), current_user, now();
SELECT sys_postmaster_start_time();
SELECT date_trunc('second', now() - sys_postmaster_start_time()) AS uptime;
SHOW server_version;
SHOW data_directory;
SELECT name, setting FROM sys_settings WHERE name IN ('port','listen_addresses');
SELECT sys_conf_load_time();

2.2 连接与会话

SELECT count(*) FROM sys_stat_activity;
SELECT state, count(*) FROM sys_stat_activity GROUP BY state;
SELECT count(*) FROM sys_stat_activity WHERE state = 'active';
SELECT usename, count(*) FROM sys_stat_activity GROUP BY usename ORDER BY 2 DESC;
SELECT datname, count(*) FROM sys_stat_activity GROUP BY datname;
SELECT pid,usename,datname,client_addr,state,wait_event_type,wait_event,query_start FROM sys_stat_activity WHERE state <> 'idle' ORDER BY query_start;
SELECT setting FROM sys_settings WHERE name = 'max_connections';
SELECT round((SELECT count(*) FROM sys_stat_activity)::numeric * 100 / (SELECT setting::int FROM sys_settings WHERE name='max_connections'), 2) AS conn_pct;
SELECT * FROM sys_stat_activity WHERE backend_type = 'client backend' AND state = 'idle in transaction';
SELECT pid, now()-xact_start AS xact_age, state, query FROM sys_stat_activity WHERE xact_start IS NOT NULL ORDER BY xact_start LIMIT 20;
SELECT pid, now()-state_change AS idle_sec, query FROM sys_stat_activity WHERE state LIKE 'idle%' ORDER BY state_change LIMIT 20;
SELECT * FROM sys_stat_database;

2.3 空间与对象

SELECT datname, sys_size_pretty(sys_database_size(datname)) FROM sys_database ORDER BY sys_database_size(datname) DESC;
SELECT sys_size_pretty(sys_database_size(current_database()));
SELECT spcname, sys_size_pretty(sys_tablespace_size(spcname)) FROM sys_tablespace;
SELECT relname, sys_size_pretty(sys_total_relation_size(oid)) FROM sys_class WHERE relkind='r' ORDER BY sys_total_relation_size(oid) DESC LIMIT 20;
SELECT nspname, sys_size_pretty(sum(sys_total_relation_size(c.oid))) FROM sys_class c JOIN sys_namespace n ON n.oid=c.relnamespace WHERE relkind='r' GROUP BY 1 ORDER BY sum(sys_total_relation_size(c.oid)) DESC;
SELECT relname, n_live_tup, n_dead_tup, last_vacuum, last_autovacuum, last_analyze FROM sys_stat_user_tables ORDER BY n_dead_tup DESC LIMIT 20;
SELECT schemaname, relname, seq_scan, idx_scan, seq_tup_read, n_live_tup FROM sys_stat_user_tables ORDER BY seq_scan DESC LIMIT 20;
SELECT schemaname, relname, indexrelname, idx_scan, idx_tup_read FROM sys_stat_all_indexes ORDER BY idx_scan ASC LIMIT 20;
SELECT * FROM sys_stat_bgwriter;
SELECT * FROM sys_stat_archiver;
SELECT * FROM sys_stat_progress_vacuum;
SELECT * FROM sys_stat_progress_create_index;

2.4 锁与等待

SELECT locktype, mode, granted, count(*) FROM sys_locks GROUP BY 1,2,3 ORDER BY 4 DESC;
SELECT pid, wait_event_type, wait_event, state, query FROM sys_stat_activity WHERE wait_event_type = 'Lock';
SELECT a.pid AS blocked_pid, a.query AS blocked_query, b.pid AS blocking_pid, b.query AS blocking_query FROM sys_stat_activity a JOIN sys_locks l1 ON l1.pid=a.pid AND NOT l1.granted JOIN sys_locks l2 ON l2.locktype=l1.locktype AND l2.relation IS NOT DISTINCT FROM l1.relation AND l2.granted JOIN sys_stat_activity b ON b.pid=l2.pid;
SELECT * FROM sys_locks WHERE NOT granted;
SELECT pid, relation::regclass, mode, granted FROM sys_locks WHERE relation IS NOT NULL;
SELECT count(*) FROM sys_stat_activity WHERE wait_event_type = 'IO';
SELECT wait_event_type, wait_event, count(*) FROM sys_stat_activity WHERE wait_event IS NOT NULL GROUP BY 1,2 ORDER BY 3 DESC;
SELECT * FROM sys_stat_activity WHERE state='active' AND now()-query_start > interval '5 min';
SELECT pid, query FROM sys_stat_activity WHERE backend_xmin IS NOT NULL ORDER BY age(backend_xmin) DESC LIMIT 20;
SELECT datname, age(datfrozenxid) FROM sys_database ORDER BY 2 DESC;
SELECT relname, age(relfrozenxid) FROM sys_class WHERE relkind='r' ORDER BY 2 DESC LIMIT 20;
SELECT count(*) FROM sys_prepared_xacts;
SELECT * FROM sys_prepared_xacts ORDER BY prepared;

2.5 WAL、归档与复制

SELECT slot_name, slot_type, active, restart_lsn, sys_size_pretty(sys_wal_lsn_diff(sys_current_wal_lsn(), restart_lsn)) FROM sys_replication_slots;
SELECT * FROM sys_stat_replication;
SELECT client_addr, state, sync_state, sys_wal_lsn_diff(sent_lsn, replay_lsn) AS replay_lag_bytes FROM sys_stat_replication;
SELECT application_name, state, sys_wal_lsn_diff(sys_current_wal_lsn(), replay_lsn) AS lag_bytes FROM sys_stat_replication;
SELECT sys_last_wal_receive_lsn(), sys_last_wal_replay_lsn();
SELECT sys_current_wal_lsn(), sys_last_wal_replay_lsn();
SELECT sys_wal_lsn_diff(sys_last_wal_receive_lsn(), sys_last_wal_replay_lsn()) AS apply_lag;
SHOW wal_level; SHOW archive_mode; SHOW archive_command;
SELECT name, setting FROM sys_settings WHERE name IN ('wal_level','archive_mode','archive_command','max_wal_size','min_wal_size');
ls -l $KINGBASE_DATA/pg_wal | tail -20：查看在线 WAL 文件
SELECT count(*) FROM sys_ls_waldir();
SELECT archived_count, failed_count, last_archived_wal, last_failed_wal FROM sys_stat_archiver;
du -sh /backup/wal_archive：归档目录容量
SHOW autovacuum; SHOW autovacuum_naptime; SHOW autovacuum_max_workers;

2.6 膨胀与自动清理

SELECT * FROM sys_stat_activity WHERE backend_type LIKE '%autovacuum%';
SELECT relname, n_dead_tup, round(n_dead_tup*100.0/nullif(n_live_tup+n_dead_tup,0),2) AS dead_pct FROM sys_stat_user_tables ORDER BY dead_pct DESC LIMIT 20;
SELECT * FROM sys_stat_progress_vacuum;
SELECT relname, last_autovacuum, autovacuum_count FROM sys_stat_user_tables WHERE last_autovacuum IS NULL AND n_dead_tup > 1000;
SELECT relname FROM sys_stat_user_tables WHERE last_analyze IS NULL;
SELECT count(*) FROM sys_stat_activity WHERE query LIKE '%autovacuum%';
SELECT name, setting, unit FROM sys_settings WHERE name LIKE '%timeout%';

2.7 日志检查

SHOW log_min_duration_statement;
SHOW log_directory; SHOW log_filename; SHOW logging_collector;
tail -n 200 $KINGBASE_DATA/log/*.log
grep -c "ERROR" $KINGBASE_DATA/log/*.log
grep "FATAL" $KINGBASE_DATA/log/*.log | tail -50
grep "deadlock detected" $KINGBASE_DATA/log/*.log | tail -20
grep -i "out of memory" $KINGBASE_DATA/log/*.log | tail -20
df -h：文件系统使用率
df -i：inode 使用率

2.8 主机资源

free -m
top -b -n1 | head -20
iostat -x 1 3
vmstat 1 5
sar -u 1 5
ss -lntp | grep 54321
ps -ef | grep kingbase
uptime
dmesg | tail -50
cat /proc/meminfo
du -sh $KINGBASE_DATA
find $KINGBASE_DATA -type f -size +1G -exec ls -lh {} \;
SELECT * FROM sys_stat_ssl;
SELECT * FROM sys_file_settings;
SELECT * FROM sys_hba_file_rules;


三、性能优化与 SQL 诊断（121–220）
3.1 执行计划

EXPLAIN SELECT * FROM t WHERE id = 1;
EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM t WHERE id = 1;
EXPLAIN (ANALYZE, BUFFERS, VERBOSE, FORMAT JSON) SELECT ...;
EXPLAIN (COSTS OFF) SELECT ...;
EXPLAIN (ANALYZE, TIMING OFF) SELECT ...;

3.2 SQL 统计

SELECT * FROM sys_stat_statements ORDER BY total_exec_time DESC LIMIT 20;
SELECT * FROM sys_stat_statements ORDER BY mean_exec_time DESC LIMIT 20;
SELEC
